+							 "#gpio-cells", 0, 0, &args);
+		if (ret)
+			/* try the ancient way */
+			ret = fwnode_property_get_reference_args(fwnode, "gpios",
+								 "#gpio-cells", 0, 1, &args);
+		if (ret)
+			return ERR_PTR(ret);
+
+		if (args.nargs < 1) {
+			fwnode_handle_put(args.fwnode);
+			return ERR_PTR(-EINVAL);
+		}
+	} else {
+		/* legacy system without device tree */
+		args.fwnode = NULL;
+		args.args[0] = 0;
+		args.nargs = 0;
+	}
+
+	scl = kzalloc(sizeof(*scl), GFP_KERNEL);
+	if (!scl) {
+		fwnode_handle_put(args.fwnode);
+		return ERR_PTR(-ENOMEM);
+	}
