+	list_lru_add(&sbinfo->shrinklist, &info->shrinklist, nid, memcg);
+	info->shrinklist_memcg = memcg;
+	info->shrinklist_nid = nid;
+	memcg = NULL;
+
+unlock:
+	spin_unlock(&info->lock);
+	mem_cgroup_put(memcg);
+	return;
+
