-static int padata_replace(struct padata_instance *pinst, int offlining_cpu)
-{
-	struct padata_shell *ps;
-	int err = 0;
-
-	pinst->flags |= PADATA_RESET;
-
-	list_for_each_entry(ps, &pinst->pslist, list) {
-		err = padata_replace_one(ps, offlining_cpu);
-		if (err)
-			break;
-	}
